window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e97ce346033a6325"]={"versions": [{"id": "FIG-e97ce346033a6325", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P07mProtect</code> im AUTOSAR E2E-Protokoll (Profile 7m). Das Diagramm modelliert den internen Funktionsablauf der End-to-End-Absicherung von Multiplex- bzw. flexiblen Kommunikationsdaten vor dem Senden innerhalb der AUTOSAR-Laufzeitumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die Funktionsschnittstelle:</p>\n<ul class=\"fig-list\">\n<li>Funktion: <code>E2E_P07mProtect(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code></li>\n<li><code>Config</code>: Konfigurationsparameter des E2E-Profils 7m</li>\n<li><code>State</code>: Zustandsspeicher für den Schutzablauf (beinhaltet u. a. den Sequenzzähler)</li>\n<li><code>SourceID</code>: Quellidentifikator der Nachricht</li>\n<li><code>MessageType</code>: Typ der Nachricht</li>\n<li><code>MessageResult</code>: Ergebnisstatus der Nachricht</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (Payload)</li>\n<li><code>Length</code>: Länge des Daten-Arrays in Bytes</li>\n</ul>\n<p class=\"fig-p\">Aktionen (Activities mit Call-Behavior-Symbol):</p>\n<ul class=\"fig-list\">\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Write SourceID</code></li>\n<li><code>Write Message Type</code></li>\n<li><code>Write Message Result</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n</ul>\n<p class=\"fig-p\">Verzweigungsbedingungen (Guards):</p>\n<ul class=\"fig-list\">\n<li><code>[null input]</code></li>\n<li><code>[wrong input]</code></li>\n<li><code>[input ok]</code></li>\n</ul>\n<p class=\"fig-p\">Ablaufendpunkte:</p>\n<ul class=\"fig-list\">\n<li>Drei Aktivitätsendknoten (<code>return</code>) für die Fehler- bzw. Erfolgsfälle.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf startet am Initialknoten beim Aufruf von <code>E2E_P07mProtect</code>:</p>\n<ol class=\"fig-list\">\n<li><code>Verify inputs of the protect function</code>: Validierung aller Eingabeparameter.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trifft <code>[null input]</code> zu, verzweigt der Pfad nach links direkt zum Aktivitätsendknoten (<code>return</code>).</li>\n<li>Trifft <code>[wrong input]</code> zu, verzweigt der Pfad nach rechts direkt zum Aktivitätsendknoten (<code>return</code>).</li>\n<li>Trifft <code>[input ok]</code> zu, wird der sequentielle Hauptpfad durchlaufen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>Compute offset</code>: Berechnung des Byte-Offsets für den Header bzw. die Profil-spezifischen E2E-Felder in <code>Data</code>.</li>\n<li><code>Write Length</code>: Schreiben des Längenfelds in den Datenpuffer.</li>\n<li><code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in den Datenpuffer.</li>\n<li><code>Write DataID</code>: Eintragen des eindeutigen Datenbezeichners.</li>\n<li><code>Write SourceID</code>: Eintragen des Quellidentifikators.</li>\n<li><code>Write Message Type</code>: Schreiben des Nachrichtentyps.</li>\n<li><code>Write Message Result</code>: Schreiben des Nachrichtenergebnisses.</li>\n<li><code>Compute CRC</code>: Berechnung der Prüfsumme über die festgelegten Daten- und Headerbereiche.</li>\n<li><code>Write CRC</code>: Schreiben des berechneten CRC-Werts in den Datenpuffer.</li>\n<li><code>Increment Counter</code>: Inkrementieren des Sequenzzählers im Zustand <code>State</code> für die nachfolgende Nachricht.</li>\n<li>Beendigung über den mittleren Aktivitätsendknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00799]</code> ist das dargestellte Gesamtverhalten von <code>E2E_P07mProtect()</code> normativ bindend.</p>\n<ul class=\"fig-list\">\n<li>Eingangsparameter müssen vor jeder Pufferoperation strikt auf <code>NULL</code>-Zeiger und Wertebereichsverletzungen geprüft werden.</li>\n<li>Bei Parameterfehlern bricht die Funktion ohne Modifikation der Nutzdaten oder Zählerstände ab.</li>\n<li>Die Inkrementierung des Zählers erfolgt ausschließlich nach erfolgreicher Pufferbefüllung und CRC-Berechnung.</li>\n<li>Implementierer müssen sicherstellen, dass die Reihenfolge der Schreiboperationen im Puffer exakt den Feldoffsets und dem Serialisierungsformat des Profils 7m entspricht.</li>\n</ul>"}, {"id": "FIG-ae3b81e6513642fe", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Schutzfunktion <code>E2E_P07mProtect</code> im AUTOSAR E2E-Protokoll (Profile 7m). Das Diagramm modelliert den internen Funktionsablauf der End-to-End-Absicherung von Multiplex- bzw. flexiblen Kommunikationsdaten vor dem Senden innerhalb der AUTOSAR-Laufzeitumgebung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm beschreibt die Funktionsschnittstelle:</p>\n<ul class=\"fig-list\">\n<li>Funktion: <code>E2E_P07mProtect(Config, State, SourceID, MessageType, MessageResult, Data, Length)</code></li>\n<li><code>Config</code>: Konfigurationsparameter des E2E-Profils 7m</li>\n<li><code>State</code>: Zustandsspeicher für den Schutzablauf (beinhaltet u. a. den Sequenzzähler)</li>\n<li><code>SourceID</code>: Quellidentifikator der Nachricht</li>\n<li><code>MessageType</code>: Typ der Nachricht</li>\n<li><code>MessageResult</code>: Ergebnisstatus der Nachricht</li>\n<li><code>Data</code>: Zeiger auf das zu schützende Daten-Array (Payload)</li>\n<li><code>Length</code>: Länge des Daten-Arrays in Bytes</li>\n</ul>\n<p class=\"fig-p\">Aktionen (Activities mit Call-Behavior-Symbol):</p>\n<ul class=\"fig-list\">\n<li><code>Verify inputs of the protect function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Write Length</code></li>\n<li><code>Write Counter</code></li>\n<li><code>Write DataID</code></li>\n<li><code>Write SourceID</code></li>\n<li><code>Write Message Type</code></li>\n<li><code>Write Message Result</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Write CRC</code></li>\n<li><code>Increment Counter</code></li>\n</ul>\n<p class=\"fig-p\">Verzweigungsbedingungen (Guards):</p>\n<ul class=\"fig-list\">\n<li><code>[null input]</code></li>\n<li><code>[wrong input]</code></li>\n<li><code>[input ok]</code></li>\n</ul>\n<p class=\"fig-p\">Ablaufendpunkte:</p>\n<ul class=\"fig-list\">\n<li>Drei Aktivitätsendknoten (<code>return</code>) für die Fehler- bzw. Erfolgsfälle.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf startet am Initialknoten beim Aufruf von <code>E2E_P07mProtect</code>:</p>\n<ol class=\"fig-list\">\n<li><code>Verify inputs of the protect function</code>: Validierung aller Eingabeparameter.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Trifft <code>[null input]</code> zu, verzweigt der Pfad nach links direkt zum Aktivitätsendknoten (<code>return</code>).</li>\n<li>Trifft <code>[wrong input]</code> zu, verzweigt der Pfad nach rechts direkt zum Aktivitätsendknoten (<code>return</code>).</li>\n<li>Trifft <code>[input ok]</code> zu, wird der sequentielle Hauptpfad durchlaufen:</li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>Compute offset</code>: Berechnung des Byte-Offsets für den Header bzw. die Profil-spezifischen E2E-Felder in <code>Data</code>.</li>\n<li><code>Write Length</code>: Schreiben des Längenfelds in den Datenpuffer.</li>\n<li><code>Write Counter</code>: Schreiben des aktuellen Alive-Counters in den Datenpuffer.</li>\n<li><code>Write DataID</code>: Eintragen des eindeutigen Datenbezeichners.</li>\n<li><code>Write SourceID</code>: Eintragen des Quellidentifikators.</li>\n<li><code>Write Message Type</code>: Schreiben des Nachrichtentyps.</li>\n<li><code>Write Message Result</code>: Schreiben des Nachrichtenergebnisses.</li>\n<li><code>Compute CRC</code>: Berechnung der Prüfsumme über die festgelegten Daten- und Headerbereiche.</li>\n<li><code>Write CRC</code>: Schreiben des berechneten CRC-Werts in den Datenpuffer.</li>\n<li><code>Increment Counter</code>: Inkrementieren des Sequenzzählers im Zustand <code>State</code> für die nachfolgende Nachricht.</li>\n<li>Beendigung über den mittleren Aktivitätsendknoten (<code>return</code>).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Gemäß Anforderung <code>[PRS_E2E_00799]</code> ist das dargestellte Gesamtverhalten von <code>E2E_P07mProtect()</code> normativ bindend.</p>\n<ul class=\"fig-list\">\n<li>Eingangsparameter müssen vor jeder Pufferoperation strikt auf <code>NULL</code>-Zeiger und Wertebereichsverletzungen geprüft werden.</li>\n<li>Bei Parameterfehlern bricht die Funktion ohne Modifikation der Nutzdaten oder Zählerstände ab.</li>\n<li>Die Inkrementierung des Zählers erfolgt ausschließlich nach erfolgreicher Pufferbefüllung und CRC-Berechnung.</li>\n<li>Implementierer müssen sicherstellen, dass die Reihenfolge der Schreiboperationen im Puffer exakt den Feldoffsets und dem Serialisierungsformat des Profils 7m entspricht.</li>\n</ul>"}], "trans": [{"from": "FIG-e97ce346033a6325", "to": "FIG-ae3b81e6513642fe", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
